CREATE TYPE "payment_method" AS ENUM ('CASH', 'BANK_TRANSFER', 'MOBILE_BANKING', 'CHEQUE', 'OTHER');
CREATE TYPE "payment_status" AS ENUM ('POSTED', 'REVERSED');
CREATE TABLE "payment_sequences" ("school_id" UUID NOT NULL, "year" INTEGER NOT NULL, "next_number" INTEGER NOT NULL DEFAULT 1, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "payment_sequences_pkey" PRIMARY KEY ("school_id", "year"), CONSTRAINT "payment_sequences_next_check" CHECK ("next_number" > 0));
CREATE TABLE "payments" ("id" UUID NOT NULL, "school_id" UUID NOT NULL, "payment_number" VARCHAR(60) NOT NULL, "amount_minor" BIGINT NOT NULL, "currency" CHAR(3) NOT NULL DEFAULT 'BDT', "payment_method" "payment_method" NOT NULL, "reference_number" VARCHAR(150), "received_on" DATE NOT NULL, "status" "payment_status" NOT NULL DEFAULT 'POSTED', "idempotency_key" VARCHAR(150), "request_hash" CHAR(64), "recorded_by" UUID NOT NULL, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "payments_pkey" PRIMARY KEY ("id"), CONSTRAINT "payments_school_id_id_key" UNIQUE ("school_id", "id"), CONSTRAINT "payments_school_id_payment_number_key" UNIQUE ("school_id", "payment_number"), CONSTRAINT "payments_amount_check" CHECK ("amount_minor" > 0), CONSTRAINT "payments_idempotency_shape_check" CHECK (("idempotency_key" IS NULL AND "request_hash" IS NULL) OR ("idempotency_key" IS NOT NULL AND "request_hash" IS NOT NULL)));
CREATE UNIQUE INDEX "payments_school_id_idempotency_key_unique" ON "payments"("school_id", "idempotency_key") WHERE "idempotency_key" IS NOT NULL;
CREATE INDEX "payments_school_id_received_on_idx" ON "payments"("school_id", "received_on");
CREATE TABLE "payment_allocations" ("id" UUID NOT NULL, "school_id" UUID NOT NULL, "payment_id" UUID NOT NULL, "invoice_id" UUID NOT NULL, "amount_minor" BIGINT NOT NULL, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "payment_allocations_pkey" PRIMARY KEY ("id"), CONSTRAINT "payment_allocations_school_id_id_key" UNIQUE ("school_id", "id"), CONSTRAINT "payment_allocations_once_key" UNIQUE ("school_id", "payment_id", "invoice_id"), CONSTRAINT "payment_allocations_amount_check" CHECK ("amount_minor" > 0));
CREATE INDEX "payment_allocations_school_id_invoice_id_idx" ON "payment_allocations"("school_id", "invoice_id");
CREATE INDEX "payment_allocations_school_id_payment_id_idx" ON "payment_allocations"("school_id", "payment_id");
CREATE TABLE "payment_reversals" ("id" UUID NOT NULL, "school_id" UUID NOT NULL, "payment_id" UUID NOT NULL, "reason" TEXT NOT NULL, "reversed_by" UUID NOT NULL, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "payment_reversals_pkey" PRIMARY KEY ("id"), CONSTRAINT "payment_reversals_school_id_id_key" UNIQUE ("school_id", "id"), CONSTRAINT "payment_reversals_school_id_payment_id_key" UNIQUE ("school_id", "payment_id"));
ALTER TABLE "payment_sequences" ADD CONSTRAINT "payment_sequences_school_fkey" FOREIGN KEY ("school_id") REFERENCES "schools"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "payments" ADD CONSTRAINT "payments_school_fkey" FOREIGN KEY ("school_id") REFERENCES "schools"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "payments" ADD CONSTRAINT "payments_recorder_same_school_fkey" FOREIGN KEY ("school_id", "recorded_by") REFERENCES "users"("school_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "payment_allocations" ADD CONSTRAINT "payment_allocations_school_fkey" FOREIGN KEY ("school_id") REFERENCES "schools"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "payment_allocations" ADD CONSTRAINT "payment_allocations_payment_same_school_fkey" FOREIGN KEY ("school_id", "payment_id") REFERENCES "payments"("school_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "payment_allocations" ADD CONSTRAINT "payment_allocations_invoice_same_school_fkey" FOREIGN KEY ("school_id", "invoice_id") REFERENCES "invoices"("school_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "payment_reversals" ADD CONSTRAINT "payment_reversals_school_fkey" FOREIGN KEY ("school_id") REFERENCES "schools"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "payment_reversals" ADD CONSTRAINT "payment_reversals_payment_same_school_fkey" FOREIGN KEY ("school_id", "payment_id") REFERENCES "payments"("school_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "payment_reversals" ADD CONSTRAINT "payment_reversals_reverser_same_school_fkey" FOREIGN KEY ("school_id", "reversed_by") REFERENCES "users"("school_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;
